"""Private view of input lineage, not a claim of KPI impact or person risk."""
import argparse,json
from pathlib import Path
from engine import Engine,now,sha

def export_report(runtime,output):
 with Engine(runtime) as e:
  head=e.verify();run=e.db.execute('SELECT * FROM runs ORDER BY at DESC LIMIT 1').fetchone()
  if not run:raise ValueError('No accepted lineage run')
  rules=json.loads(run['rules_json'])
  if rules.get('kind')!='kpi_lineage':raise ValueError('Lineage run required')
  def read(hash_):
   row=e.db.execute('SELECT object_path FROM snapshots WHERE hash=?',(hash_,)).fetchone()
   if not row:raise ValueError('Missing lineage artifact')
   return json.loads((e.root/row[0]).read_bytes())
  result=read(run['snapshot_hash']);findings={}
  for role in ['invoice_findings','scan_findings']:
   for finding in read(rules['reference_sources'][role]):findings[finding['fingerprint']]=finding
  used={x['finding_fingerprint'] for k in result['invoice_kpis'] for x in k['links']}|{x['finding_fingerprint'] for r in result['perfect_store'] for c in r['components'] for x in c['links']}
  result.update(findings={key:findings[key] for key in used},run_id=run['id'],result_sha256=run['snapshot_hash'],ledger_head=head,generated_at=now(),artifact_hashes=rules['reference_sources'])
 text='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MindTEC · Linaje de señales hacia KPI</title><style>body{font:15px system-ui;margin:0;background:#eff3f8;color:#21354c}main{max-width:1250px;margin:auto;padding:25px}.card{background:white;border:1px solid #d6e0ed;border-radius:12px;padding:22px;margin:18px 0}.note{background:#fff5e8;border-left:4px solid #bd8439;padding:15px}.filters{display:flex;gap:14px;flex-wrap:wrap}label{display:block}button,select{font:inherit;padding:9px;border:1px solid #bfcfe0;border-radius:6px;background:white;color:inherit}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:11px;text-align:left;border-bottom:1px solid #dce5ef;vertical-align:top}th{background:#edf3fa}.scroll{overflow:auto}pre,code{font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere}small{color:#5a7089}</style><main><h1>De la señal al insumo del indicador</h1><p>12 KPI históricos y componentes del Perfect Store reciente · cortes separados y evidencia conservada</p><div class="note">Un vínculo indica que el indicador declara utilizar una línea señalada, o que un componente cita la misma respuesta original. No demuestra que cambió el valor del indicador. No se modifica ningún dato, exclusión ni decisión humana. La ausencia de vínculos tampoco acredita una validación.</div><section class="card"><div class="filters"><label>Vista<select id="view"><option value="kpi">12 KPI históricos · líneas de factura</option><option value="ps">Perfect Store · respuestas Scan</option></select></label><label>Mes<select id="month"></select></label><label>Marca<select id="brand"></select></label><label>Mostrar<select id="scope"><option value="linked">Solo resultados con vínculos</option><option value="all">Todos los resultados y sus estados</option></select></label></div><p id="count"></p><div id="rows" class="scroll"></div><p><button id="prev">Anterior</button> <button id="next">Siguiente</button> <button id="download">Exportar linaje completo JSON</button></p></section><section class="card"><h2>Identidad de las fuentes</h2><p>Los KPI históricos conservan sus valores publicados y operativos. Perfect Store procede de su propio corte reciente; esta vista no sustituye ni recalcula ambos.</p><div id="trace"></div><p>Este HTML es una instantánea. Los originales y las huellas se conservan en el runtime privado de linaje. Las señales requieren interpretación documental y no son acusaciones de fraude.</p></section></main><script id="data" type="application/json">__DATA__</script><script>const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let page=0;const brands=[...new Set([...D.invoice_kpis,...D.perfect_store].map(r=>r.brand))].sort();$('brand').innerHTML='<option value="">Todas las marcas</option>'+brands.map(b=>'<option>'+E(b)+'</option>').join('');$('month').innerHTML='<option value="">Todos los meses</option>'+[...new Set([...D.invoice_kpis,...D.perfect_store].map(r=>r.month))].sort().map(m=>'<option>'+E(m)+'</option>').join('');function signal(x){const f=D.findings[x.finding_fingerprint];return '<details><summary>'+E(f.title)+' · '+E(f.severity)+'</summary><p>'+E(f.explanation)+'</p><pre>'+E(JSON.stringify(f.evidence,null,2))+'</pre><code>'+E(f.fingerprint)+'</code></details>'}function render(){const ps=$('view').value==='ps';let rows=(ps?D.perfect_store:D.invoice_kpis).filter(r=>(!$('month').value||r.month===$('month').value)&&(!$('brand').value||r.brand===$('brand').value));if($('scope').value==='linked')rows=rows.filter(r=>ps?r.components.some(c=>c.links.length):r.links.length);const total=rows.length;rows=rows.slice(page*50,page*50+50);$('count').textContent=total+' resultados del filtro · página '+(page+1)+' de '+Math.max(1,Math.ceil(total/50))+'. Impacto numérico: no establecido.';$('rows').innerHTML='<table><thead><tr>'+['Mes / marca / categoría',ps?'Visita y componentes':'Indicador y valor conservado','Vínculos y evidencia','Alcance'].map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr><td>'+E(r.month)+'<br><b>'+E(r.brand)+'</b><br>'+E(r.category)+'</td><td>'+(ps?'Visita '+E(r.record_id)+'<br>'+E(r.company):E(r.indicator)+'<p>Publicado: '+E(r.published??'No disponible')+'<br>Operativo: '+E(r.operational_value??'No calculado')+'</p>')+'</td><td>'+(ps?r.components.filter(c=>$('scope').value==='all'||c.links.length).map(c=>'<b>'+E(c.component)+'</b> · '+E(c.state)+' · valor '+E(c.value===null?'pendiente / no aplica':c.value)+'<p>'+c.links.map(signal).join('')+'</p><details><summary>Rutas verificadas ('+c.verified_paths.length+')</summary><pre>'+E(c.verified_paths.join('\n'))+'</pre></details>').join(''):r.links.map(x=>'<b>Línea '+E(x.line_key)+'</b><br>Campos: '+E(x.paths.join(', '))+signal(x)).join('')||'Sin vínculos encontrados en las dependencias declaradas.')+'</td><td>'+(ps?E(r.components.reduce((n,c)=>n+c.unresolved_paths.length,0))+' rutas sin resolver':E(r.declared_dependencies)+' dependencias de factura<br>'+E(r.missing_dependencies.length)+' ausentes · '+E(r.ambiguous_dependencies.length)+' ambiguas<br><small>'+E(r.status)+'</small>')+'<p>No se calcula un cambio del KPI a partir de esta coincidencia.</p></td></tr>').join('')+'</tbody></table>';$('prev').disabled=page===0;$('next').disabled=(page+1)*50>=total}for(const id of ['view','month','brand','scope'])$(id).onchange=()=>{page=0;render()};$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};$('download').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(D,null,2)],{type:'application/json'}));a.download='MindTEC_linaje_de_senales.json';a.click();URL.revokeObjectURL(a.href)};$('trace').innerHTML='<pre>'+E(JSON.stringify({run:D.run_id,result_sha256:D.result_sha256,invoice_run:D.invoice_run,scan_run:D.scan_run,artifacts:D.artifact_hashes,ledger_head:D.ledger_head,generated_at:D.generated_at},null,2))+'</pre>';render();</script></html>'''
 # Backslash-newline must survive the Python template as a JS string escape.
 text=text.replace("join('\n')","join('\\n')").replace('__DATA__',json.dumps(result,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c'))
 output=Path(output);output.parent.mkdir(parents=True,exist_ok=True);output.write_text(text,encoding='utf-8')
 return {'output':str(output.resolve()),'run_id':run['id'],'sha256_html':sha(output.read_bytes())}

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--runtime',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();print(json.dumps(export_report(a.runtime,a.output)))
